FUNCTION_BLOCK FB_SteelSkinPass_RollEccentricityElongation
(*
========================================================================================================================
  METALLURGY & INDUSTRIAL AUTOMATION ARCHITECTURE:
  4-HIGH SKIN-PASS TEMPER ROLLING MILL (SPM) - HYDRAULIC GAP & FLATNESS ELONGATION CONTROL
  Cyber-Physical Systems Control Architecture complying with IEC 61131-3 3rd Ed. & IEC 61508 SIL-3 TMR
  Execution Interval: 2.0 ms Deterministic Cyclic Task (500 Hz Synchronous Industrial Ethernet)
========================================================================================================================
  1. METALLURGICAL PROCESS OBJECTIVE:
     Suppression of yield-point elongation (Lüders bands) via 0.20% to 2.50% dynamic plastic temper elongation.
     Simultaneous regulation of optical strip flatness across 16 zones in I-units (1 I-unit = 10^-5 strain differential).
     Dynamic transfer of work roll texture (Ra and RPc) under strict roll force equilibrium.

  2. LOADED ROLL GAP & MILL STRETCH DYNAMICS:
     Stone-Bland-Ford formulation: h_exit(t) = S_0(t) + F_total(t)/M_mill - Delta_ecc(t) - Delta_thermal(t)
     Mill housing modulus M_mill = 4500.0 kN/mm; Total separating forces up to 22,000 kN.

  3. ADAPTIVE ROLL ECCENTRICITY COMPENSATION (REC):
     Backup Rolls (BUR) and Work Rolls (WR) geometric out-of-roundness and bearing ovality are compensated via
     multi-harmonic Recursive Least Squares (RLS) Fourier series estimators locked to high-resolution roll resolvers:
     F_ecc(t) = Sum_{r=1..4} Sum_{h=1..4} [ A_(r,h)*cos(h*theta_r) + B_(r,h)*sin(h*theta_r) ]
     Feedforward position trims: Delta_S_ecc = -0.5 * (F_ecc / M_mill) * G_comp.

  4. OPTICAL FLATNESS ORTHOGONAL MODAL DECOMPOSITION:
     16-channel optical triangulation profile decomposed via discrete Legendre polynomials:
     P0 (Mean Elongation), P1 (Linear Wedge / Tilt), P2 (Parabolic Crown / Bending), P4 (Quarter-buckle / Cooling).

  5. MODEL PREDICTIVE CONTROL (MPC) & 2oo3 TMR FAULT TOLERANCE:
     Discrete-time 6-state, 4-input state-space formulation with projected gradient descent quadratic solver.
     Triple Modular Redundancy (2oo3) on all velocity and roll force channels with median voting and degradation.
*)

VAR_INPUT
    (* Supervisory Execution & Safety Interlocks *)
    bEnable                         : BOOL;     (* Master operational enable signal from Line PLC *)
    bEmergencyStopOk                : BOOL;     (* Hardwired E-Stop safety circuit healthy (Active HIGH) *)
    bResetAlarms                    : BOOL;     (* Operator fault acknowledgement and alarm latch reset *)
    bCalibrationMode                : BOOL;     (* Enable manual roll gap zeroing and kiss-pass calibration *)

    (* 2oo3 Triple Modular Redundancy Velocity Feedback [m/min] *)
    rStripSpeedEntry_RawA_mpm       : REAL;     (* Entry strip velocity: Laser Doppler Velocimeter A [m/min] *)
    rStripSpeedEntry_RawB_mpm       : REAL;     (* Entry strip velocity: Laser Doppler Velocimeter B [m/min] *)
    rStripSpeedEntry_RawC_mpm       : REAL;     (* Entry strip velocity: Bridle Roll Pulse Tachometer C [m/min] *)
    rStripSpeedExit_RawA_mpm        : REAL;     (* Exit strip velocity: Laser Doppler Velocimeter A [m/min] *)
    rStripSpeedExit_RawB_mpm        : REAL;     (* Exit strip velocity: Laser Doppler Velocimeter B [m/min] *)
    rStripSpeedExit_RawC_mpm        : REAL;     (* Exit strip velocity: Bridle Roll Pulse Tachometer C [m/min] *)

    (* 2oo3 Triple Modular Redundancy Roll Separating Force Feedback [kN] *)
    rRollForce_DS_RawA_kN           : REAL;     (* Drive Side Roll Force: Strain-gauge Load Cell A [kN] *)
    rRollForce_DS_RawB_kN           : REAL;     (* Drive Side Roll Force: Strain-gauge Load Cell B [kN] *)
    rRollForce_DS_RawC_kN           : REAL;     (* Drive Side Roll Force: Hydraulic Pressure Equivalent C [kN] *)
    rRollForce_OS_RawA_kN           : REAL;     (* Operator Side Roll Force: Strain-gauge Load Cell A [kN] *)
    rRollForce_OS_RawB_kN           : REAL;     (* Operator Side Roll Force: Strain-gauge Load Cell B [kN] *)
    rRollForce_OS_RawC_kN           : REAL;     (* Operator Side Roll Force: Hydraulic Pressure Equivalent C [kN] *)

    (* Hydraulic Gap Cylinder LVDT Position Feedbacks [mm] *)
    rRollGap_DS_mm                  : REAL;     (* LVDT cylinder position feedback Drive Side [mm] *)
    rRollGap_OS_mm                  : REAL;     (* LVDT cylinder position feedback Operator Side [mm] *)

    (* Roll Rotational Resolver Angles [deg] (0.0 to 360.0 deg) *)
    rBackupRollAngleTop_deg         : REAL;     (* Top Backup Roll resolver position [deg] *)
    rBackupRollAngleBot_deg         : REAL;     (* Bottom Backup Roll resolver position [deg] *)
    rWorkRollAngleTop_deg           : REAL;     (* Top Work Roll resolver position [deg] *)
    rWorkRollAngleBot_deg           : REAL;     (* Bottom Work Roll resolver position [deg] *)

    (* Optical Multi-Channel Transverse Flatness Profile [I-unit] *)
    arrFlatnessProfile_Iunit        : ARRAY[1..16] OF REAL; (* Transverse optical flatness 16 zones [I-unit] *)

    (* Process Setpoints & Incoming Strip Recipe *)
    rTargetElongation_pct           : REAL;     (* Recipe target plastic elongation [%] (0.20% to 2.50%) *)
    rTargetBendingForce_kN          : REAL;     (* Base work roll bending setpoint [kN] (-600 to +1200 kN) *)
    rStripWidth_mm                  : REAL;     (* Processed strip width [mm] (900.0 to 1850.0 mm) *)
    rStripThickness_mm              : REAL;     (* Nominal incoming strip gauge [mm] (0.35 to 2.50 mm) *)
    rStripTensionEntry_kN           : REAL;     (* Entry tensiometer roll strip tension [kN] *)
    rStripTensionExit_kN            : REAL;     (* Exit tensiometer roll strip tension [kN] *)
    bTailOutApproaching             : BOOL;     (* Coil tail-out detector flag (weld hole / laser sensor) *)
END_VAR

VAR_OUTPUT
    (* Operational State & Interlock Status *)
    bSystemReady                    : BOOL;     (* Stand interlocks, hydraulics, and instruments healthy *)
    bControlActive                  : BOOL;     (* Dynamic closed-loop elongation & flatness MPC active *)
    bDegradedMode                   : BOOL;     (* Stand running in degraded sensor redundancy mode *)
    bSystemAlarm                    : BOOL;     (* Master trip/abort alarm active *)
    wWarningWord                    : WORD;     (* Diagnostic warning bitmask *)
    wFaultCode                      : WORD;     (* Master shutdown fault code *)

    (* Metallurgical Process Feedback Variables *)
    rElongationFeedback_pct         : REAL;     (* 2oo3 voted, filtered plastic strip elongation [%] *)
    rElongationError_pct            : REAL;     (* Elongation tracking error (Setpoint - Feedback) [%] *)
    rTotalRollForceFeedback_kN      : REAL;     (* 2oo3 voted total roll separating force [kN] *)
    rDifferentialForce_kN           : REAL;     (* Roll force differential (Drive Side - Operator Side) [kN] *)

    (* Optical Flatness Legendre Modal Metrics *)
    rMeanFlatness_Iunit             : REAL;     (* 0th order Legendre: Mean transverse strain [I-unit] *)
    rFlatnessTilt_Iunit             : REAL;     (* 1st order Legendre: Linear wedge / mill tilt [I-unit] *)
    rFlatnessCrown_Iunit            : REAL;     (* 2nd order Legendre: Parabolic crown [I-unit] *)
    rFlatnessQuarter_Iunit          : REAL;     (* 4th order Legendre: Symmetrical quarter-buckle [I-unit] *)

    (* Actuator Servo Command Setpoints *)
    rServoCmdGap_DS_mm              : REAL;     (* Position command to Drive Side hydraulic gap servo [mm] *)
    rServoCmdGap_OS_mm              : REAL;     (* Position command to Operator Side hydraulic gap servo [mm] *)
    rEccentricityComp_DS_mm         : REAL;     (* Drive Side real-time roll eccentricity trim [mm] *)
    rEccentricityComp_OS_mm         : REAL;     (* Operator Side real-time roll eccentricity trim [mm] *)
    rWorkRollBendingCmd_kN          : REAL;     (* Dynamic work roll bending servo valve command [kN] *)
    arrCoolingZoneTrim_pct          : ARRAY[1..16] OF REAL; (* Multi-zone roll cooling header solenoid duty cycles [%] *)

    (* Diagnostic & TMR Health Registers *)
    dwTMR_DiagnosticBits            : DWORD;    (* Bitfield recording individual sensor channel health *)
    iStateSequence                  : INT;      (* Operating state of supervisory finite state machine *)
END_VAR

VAR
    (* Mill Architectural & Mechanical Parameters *)
    c_rMillModulus_kN_per_mm        : REAL := 4500.0;   (* Combined mill housing stiffness modulus [kN/mm] *)
    c_rSamplingPeriod_sec           : REAL := 0.002;    (* Execution sample interval Ts = 2.0 ms (500 Hz) *)
    c_rPi                           : REAL := 3.141592653589793;
    c_rDegToRad                     : REAL := 0.017453292519943;
    c_rMinStripSpeedForREC_mpm      : REAL := 30.0;     (* Minimum strip speed for eccentricity learning [m/min] *)
    c_rMaxAllowableRollForce_kN     : REAL := 22000.0;  (* Critical maximum roll force trip limit [kN] *)
    c_rMaxBendingForcePositive_kN   : REAL := 1200.0;   (* Maximum positive work roll bending force [kN] *)
    c_rMaxBendingForceNegative_kN   : REAL := -600.0;   (* Maximum negative work roll bending force [kN] *)
    c_rMaxHydraulicStroke_mm        : REAL := 120.0;    (* Full open stroke of main hydraulic cylinders [mm] *)
    c_rKissPassCalibrationForce_kN  : REAL := 1500.0;   (* Target contact kiss force for zeroing [kN] *)

    (* 2oo3 TMR Voting Parameters & Internal Registers *)
    c_rSpeedDiscrepancyLimit_mpm    : REAL := 12.0;     (* Permissible speed discrepancy between channels [m/min] *)
    c_rForceDiscrepancyLimit_kN     : REAL := 350.0;    (* Permissible force discrepancy between channels [kN] *)
    rVotedEntrySpeed_mpm            : REAL := 0.0;
    rVotedExitSpeed_mpm             : REAL := 0.0;
    rVotedForce_DS_kN               : REAL := 0.0;
    rVotedForce_OS_kN               : REAL := 0.0;
    iEntrySpeedFaultCounterA        : INT := 0;
    iEntrySpeedFaultCounterB        : INT := 0;
    iEntrySpeedFaultCounterC        : INT := 0;
    iExitSpeedFaultCounterA         : INT := 0;
    iExitSpeedFaultCounterB         : INT := 0;
    iExitSpeedFaultCounterC         : INT := 0;
    iForceDS_FaultCounterA          : INT := 0;
    iForceDS_FaultCounterB          : INT := 0;
    iForceDS_FaultCounterC          : INT := 0;
    iForceOS_FaultCounterA          : INT := 0;
    iForceOS_FaultCounterB          : INT := 0;
    iForceOS_FaultCounterC          : INT := 0;
    bEntrySpeedDegraded             : BOOL := FALSE;
    bExitSpeedDegraded              : BOOL := FALSE;
    bForceDS_Degraded               : BOOL := FALSE;
    bForceOS_Degraded               : BOOL := FALSE;

    (* Orthogonal Legendre Flatness Basis Weights *)
    arrZoneCoordinate_xi            : ARRAY[1..16] OF REAL;
    arrLegendre_P0                  : ARRAY[1..16] OF REAL;
    arrLegendre_P1                  : ARRAY[1..16] OF REAL;
    arrLegendre_P2                  : ARRAY[1..16] OF REAL;
    arrLegendre_P4                  : ARRAY[1..16] OF REAL;
    arrFlatnessResidual_Iunit       : ARRAY[1..16] OF REAL;
    rNorm_P0                        : REAL := 16.0;
    rNorm_P1                        : REAL := 0.0;
    rNorm_P2                        : REAL := 0.0;
    rNorm_P4                        : REAL := 0.0;
    bLegendreBasisInitialized       : BOOL := FALSE;

    (* Adaptive Roll Eccentricity Filter Tables (4 Rolls x 4 Harmonics) *)
    arrHarmonicCos_A                : ARRAY[1..4, 1..4] OF REAL;
    arrHarmonicSin_B                : ARRAY[1..4, 1..4] OF REAL;
    rRLS_LearningGain               : REAL := 0.045;
    rEccentricityCompGain           : REAL := 0.85;
    rEstimatedEccForceDS_kN         : REAL := 0.0;
    rEstimatedEccForceOS_kN         : REAL := 0.0;
    rRollAngleRad_TopBUR            : REAL := 0.0;
    rRollAngleRad_BotBUR            : REAL := 0.0;
    rRollAngleRad_TopWR             : REAL := 0.0;
    rRollAngleRad_BotWR             : REAL := 0.0;

    (* Discrete-Time State-Space Matrices & MPC Optimizer [Ts = 2 ms] *)
    matA                            : ARRAY[1..6, 1..6] OF REAL;
    matB                            : ARRAY[1..6, 1..4] OF REAL;
    matC                            : ARRAY[1..4, 1..6] OF REAL;
    matD                            : ARRAY[1..4, 1..4] OF REAL;
    vecState_x                      : ARRAY[1..6] OF REAL;
    vecStateNext_x                  : ARRAY[1..6] OF REAL;
    vecControl_u                    : ARRAY[1..4] OF REAL;
    vecControlPrev_u                : ARRAY[1..4] OF REAL;
    vecDeltaControl_du              : ARRAY[1..4] OF REAL;
    vecGradient_g                   : ARRAY[1..4] OF REAL;
    vecCostWeight_Q                 : ARRAY[1..6] OF REAL;
    vecCostWeight_R                 : ARRAY[1..4] OF REAL;
    vecCostWeight_S                 : ARRAY[1..4] OF REAL;
    vecControlMin_u                 : ARRAY[1..4] OF REAL;
    vecControlMax_u                 : ARRAY[1..4] OF REAL;
    vecDeltaMax_du                  : ARRAY[1..4] OF REAL;
    rMPC_StepSizeAlpha              : REAL := 0.0125;
    iMPC_MaxIterations              : INT := 6;
    bMPC_MatricesInitialized        : BOOL := FALSE;

    (* Supervisory State Machine & Timers *)
    iState                          : INT := 0;
    tStepTimer                      : TON;
    tKissCalibrationTimer           : TON;
    tTailoutDecelTimer              : TON;
    rZeroGapOffset_DS_mm            : REAL := 0.0;
    rZeroGapOffset_OS_mm            : REAL := 0.0;
    rBaseGapPosition_DS_mm          : REAL := 15.0;
    rBaseGapPosition_OS_mm          : REAL := 15.0;

    (* Internal Alarms and Fault Detection Flags *)
    bSpeedVoterFailedEntry          : BOOL := FALSE;
    bSpeedVoterFailedExit           : BOOL := FALSE;
    bForceVoterFailedDS             : BOOL := FALSE;
    bForceVoterFailedOS             : BOOL := FALSE;
    bExcessiveElongationError       : BOOL := FALSE;
    bExcessiveRollForce             : BOOL := FALSE;
    bExcessiveFlatnessDistortion    : BOOL := FALSE;
    bHydraulicGapSaturation         : BOOL := FALSE;
    bBendingSaturation              : BOOL := FALSE;
    bStripBreakageSuspected         : BOOL := FALSE;
    iDiagnosticLoopIndex            : INT := 1;
END_VAR

(* ====================================================================================================================
   SECTION 1: HARD SAFETY CIRCUIT, EMERGENCY TRIP & SYSTEM SHUTDOWN INTERLOCK
   ==================================================================================================================== *)
IF NOT bEmergencyStopOk THEN
    bSystemReady            := FALSE;
    bControlActive          := FALSE;
    bDegradedMode           := FALSE;
    bSystemAlarm            := TRUE;
    wFaultCode              := 16#0001; (* EMERGENCY_STOP_HARDWIRE_TRIPPED *)
    wWarningWord            := 16#0000;
    rServoCmdGap_DS_mm      := c_rMaxHydraulicStroke_mm; (* Fully retract gap cylinders *)
    rServoCmdGap_OS_mm      := c_rMaxHydraulicStroke_mm;
    rWorkRollBendingCmd_kN  := 0.0;                      (* Depressurize roll bending jacks *)
    rEccentricityComp_DS_mm := 0.0;
    rEccentricityComp_OS_mm := 0.0;

    FOR iDiagnosticLoopIndex := 1 TO 16 DO
        arrCoolingZoneTrim_pct[iDiagnosticLoopIndex] := 0.0;
    END_FOR;

    iState := 99;
    iStateSequence := iState;
    RETURN;
END_IF;

(* ====================================================================================================================
   SECTION 2: 2oo3 TRIPLE MODULAR REDUNDANCY (TMR) SENSOR VOTING & HEALTH PLAUSIBILITY
   ==================================================================================================================== *)
(* --- 2.1 ENTRY STRIP VELOCITY 2oo3 VOTER --- *)
IF (ABS(rStripSpeedEntry_RawA_mpm - rStripSpeedEntry_RawB_mpm) <= c_rSpeedDiscrepancyLimit_mpm) THEN
    IF (ABS(rStripSpeedEntry_RawA_mpm - rStripSpeedEntry_RawC_mpm) <= c_rSpeedDiscrepancyLimit_mpm) THEN
        IF (rStripSpeedEntry_RawA_mpm >= rStripSpeedEntry_RawB_mpm AND rStripSpeedEntry_RawA_mpm <= rStripSpeedEntry_RawC_mpm) OR
           (rStripSpeedEntry_RawA_mpm <= rStripSpeedEntry_RawB_mpm AND rStripSpeedEntry_RawA_mpm >= rStripSpeedEntry_RawC_mpm) THEN
            rVotedEntrySpeed_mpm := rStripSpeedEntry_RawA_mpm;
        ELSIF (rStripSpeedEntry_RawB_mpm >= rStripSpeedEntry_RawA_mpm AND rStripSpeedEntry_RawB_mpm <= rStripSpeedEntry_RawC_mpm) OR
              (rStripSpeedEntry_RawB_mpm <= rStripSpeedEntry_RawA_mpm AND rStripSpeedEntry_RawB_mpm >= rStripSpeedEntry_RawC_mpm) THEN
            rVotedEntrySpeed_mpm := rStripSpeedEntry_RawB_mpm;
        ELSE
            rVotedEntrySpeed_mpm := rStripSpeedEntry_RawC_mpm;
        END_IF;
        iEntrySpeedFaultCounterA := 0; iEntrySpeedFaultCounterB := 0; iEntrySpeedFaultCounterC := 0;
        bEntrySpeedDegraded := FALSE;
    ELSE
        rVotedEntrySpeed_mpm := 0.5 * (rStripSpeedEntry_RawA_mpm + rStripSpeedEntry_RawB_mpm);
        iEntrySpeedFaultCounterC := iEntrySpeedFaultCounterC + 1;
        bEntrySpeedDegraded := TRUE;
    END_IF;
ELSIF (ABS(rStripSpeedEntry_RawA_mpm - rStripSpeedEntry_RawC_mpm) <= c_rSpeedDiscrepancyLimit_mpm) THEN
    rVotedEntrySpeed_mpm := 0.5 * (rStripSpeedEntry_RawA_mpm + rStripSpeedEntry_RawC_mpm);
    iEntrySpeedFaultCounterB := iEntrySpeedFaultCounterB + 1;
    bEntrySpeedDegraded := TRUE;
ELSIF (ABS(rStripSpeedEntry_RawB_mpm - rStripSpeedEntry_RawC_mpm) <= c_rSpeedDiscrepancyLimit_mpm) THEN
    rVotedEntrySpeed_mpm := 0.5 * (rStripSpeedEntry_RawB_mpm + rStripSpeedEntry_RawC_mpm);
    iEntrySpeedFaultCounterA := iEntrySpeedFaultCounterA + 1;
    bEntrySpeedDegraded := TRUE;
ELSE
    rVotedEntrySpeed_mpm := rStripSpeedEntry_RawC_mpm;
    bSpeedVoterFailedEntry := TRUE;
END_IF;

(* --- 2.2 EXIT STRIP VELOCITY 2oo3 VOTER --- *)
IF (ABS(rStripSpeedExit_RawA_mpm - rStripSpeedExit_RawB_mpm) <= c_rSpeedDiscrepancyLimit_mpm) THEN
    IF (ABS(rStripSpeedExit_RawA_mpm - rStripSpeedExit_RawC_mpm) <= c_rSpeedDiscrepancyLimit_mpm) THEN
        IF (rStripSpeedExit_RawA_mpm >= rStripSpeedExit_RawB_mpm AND rStripSpeedExit_RawA_mpm <= rStripSpeedExit_RawC_mpm) OR
           (rStripSpeedExit_RawA_mpm <= rStripSpeedExit_RawB_mpm AND rStripSpeedExit_RawA_mpm >= rStripSpeedExit_RawC_mpm) THEN
            rVotedExitSpeed_mpm := rStripSpeedExit_RawA_mpm;
        ELSIF (rStripSpeedExit_RawB_mpm >= rStripSpeedExit_RawA_mpm AND rStripSpeedExit_RawB_mpm <= rStripSpeedExit_RawC_mpm) OR
              (rStripSpeedExit_RawB_mpm <= rStripSpeedExit_RawA_mpm AND rStripSpeedExit_RawB_mpm >= rStripSpeedExit_RawC_mpm) THEN
            rVotedExitSpeed_mpm := rStripSpeedExit_RawB_mpm;
        ELSE
            rVotedExitSpeed_mpm := rStripSpeedExit_RawC_mpm;
        END_IF;
        iExitSpeedFaultCounterA := 0; iExitSpeedFaultCounterB := 0; iExitSpeedFaultCounterC := 0;
        bExitSpeedDegraded := FALSE;
    ELSE
        rVotedExitSpeed_mpm := 0.5 * (rStripSpeedExit_RawA_mpm + rStripSpeedExit_RawB_mpm);
        iExitSpeedFaultCounterC := iExitSpeedFaultCounterC + 1;
        bExitSpeedDegraded := TRUE;
    END_IF;
ELSIF (ABS(rStripSpeedExit_RawA_mpm - rStripSpeedExit_RawC_mpm) <= c_rSpeedDiscrepancyLimit_mpm) THEN
    rVotedExitSpeed_mpm := 0.5 * (rStripSpeedExit_RawA_mpm + rStripSpeedExit_RawC_mpm);
    iExitSpeedFaultCounterB := iExitSpeedFaultCounterB + 1;
    bExitSpeedDegraded := TRUE;
ELSIF (ABS(rStripSpeedExit_RawB_mpm - rStripSpeedExit_RawC_mpm) <= c_rSpeedDiscrepancyLimit_mpm) THEN
    rVotedExitSpeed_mpm := 0.5 * (rStripSpeedExit_RawB_mpm + rStripSpeedExit_RawC_mpm);
    iExitSpeedFaultCounterA := iExitSpeedFaultCounterA + 1;
    bExitSpeedDegraded := TRUE;
ELSE
    rVotedExitSpeed_mpm := rStripSpeedExit_RawC_mpm;
    bSpeedVoterFailedExit := TRUE;
END_IF;

(* --- 2.3 DRIVE SIDE ROLL SEPARATING FORCE 2oo3 VOTER --- *)
IF (ABS(rRollForce_DS_RawA_kN - rRollForce_DS_RawB_kN) <= c_rForceDiscrepancyLimit_kN) THEN
    IF (ABS(rRollForce_DS_RawA_kN - rRollForce_DS_RawC_kN) <= c_rForceDiscrepancyLimit_kN) THEN
        IF (rRollForce_DS_RawA_kN >= rRollForce_DS_RawB_kN AND rRollForce_DS_RawA_kN <= rRollForce_DS_RawC_kN) OR
           (rRollForce_DS_RawA_kN <= rRollForce_DS_RawB_kN AND rRollForce_DS_RawA_kN >= rRollForce_DS_RawC_kN) THEN
            rVotedForce_DS_kN := rRollForce_DS_RawA_kN;
        ELSIF (rRollForce_DS_RawB_kN >= rRollForce_DS_RawA_kN AND rRollForce_DS_RawB_kN <= rRollForce_DS_RawC_kN) OR
              (rRollForce_DS_RawB_kN <= rRollForce_DS_RawA_kN AND rRollForce_DS_RawB_kN >= rRollForce_DS_RawC_kN) THEN
            rVotedForce_DS_kN := rRollForce_DS_RawB_kN;
        ELSE
            rVotedForce_DS_kN := rRollForce_DS_RawC_kN;
        END_IF;
        iForceDS_FaultCounterA := 0; iForceDS_FaultCounterB := 0; iForceDS_FaultCounterC := 0;
        bForceDS_Degraded := FALSE;
    ELSE
        rVotedForce_DS_kN := 0.5 * (rRollForce_DS_RawA_kN + rRollForce_DS_RawB_kN);
        iForceDS_FaultCounterC := iForceDS_FaultCounterC + 1;
        bForceDS_Degraded := TRUE;
    END_IF;
ELSIF (ABS(rRollForce_DS_RawA_kN - rRollForce_DS_RawC_kN) <= c_rForceDiscrepancyLimit_kN) THEN
    rVotedForce_DS_kN := 0.5 * (rRollForce_DS_RawA_kN + rRollForce_DS_RawC_kN);
    iForceDS_FaultCounterB := iForceDS_FaultCounterB + 1;
    bForceDS_Degraded := TRUE;
ELSIF (ABS(rRollForce_DS_RawB_kN - rRollForce_DS_RawC_kN) <= c_rForceDiscrepancyLimit_kN) THEN
    rVotedForce_DS_kN := 0.5 * (rRollForce_DS_RawB_kN + rRollForce_DS_RawC_kN);
    iForceDS_FaultCounterA := iForceDS_FaultCounterA + 1;
    bForceDS_Degraded := TRUE;
ELSE
    rVotedForce_DS_kN := rRollForce_DS_RawC_kN;
    bForceVoterFailedDS := TRUE;
END_IF;

(* --- 2.4 OPERATOR SIDE ROLL SEPARATING FORCE 2oo3 VOTER --- *)
IF (ABS(rRollForce_OS_RawA_kN - rRollForce_OS_RawB_kN) <= c_rForceDiscrepancyLimit_kN) THEN
    IF (ABS(rRollForce_OS_RawA_kN - rRollForce_OS_RawC_kN) <= c_rForceDiscrepancyLimit_kN) THEN
        IF (rRollForce_OS_RawA_kN >= rRollForce_OS_RawB_kN AND rRollForce_OS_RawA_kN <= rRollForce_OS_RawC_kN) OR
           (rRollForce_OS_RawA_kN <= rRollForce_OS_RawB_kN AND rRollForce_OS_RawA_kN >= rRollForce_OS_RawC_kN) THEN
            rVotedForce_OS_kN := rRollForce_OS_RawA_kN;
        ELSIF (rRollForce_OS_RawB_kN >= rRollForce_OS_RawA_kN AND rRollForce_OS_RawB_kN <= rRollForce_OS_RawC_kN) OR
              (rRollForce_OS_RawB_kN <= rRollForce_OS_RawA_kN AND rRollForce_OS_RawB_kN >= rRollForce_OS_RawC_kN) THEN
            rVotedForce_OS_kN := rRollForce_OS_RawB_kN;
        ELSE
            rVotedForce_OS_kN := rRollForce_OS_RawC_kN;
        END_IF;
        iForceOS_FaultCounterA := 0; iForceOS_FaultCounterB := 0; iForceOS_FaultCounterC := 0;
        bForceOS_Degraded := FALSE;
    ELSE
        rVotedForce_OS_kN := 0.5 * (rRollForce_OS_RawA_kN + rRollForce_OS_RawB_kN);
        iForceOS_FaultCounterC := iForceOS_FaultCounterC + 1;
        bForceOS_Degraded := TRUE;
    END_IF;
ELSIF (ABS(rRollForce_OS_RawA_kN - rRollForce_OS_RawC_kN) <= c_rForceDiscrepancyLimit_kN) THEN
    rVotedForce_OS_kN := 0.5 * (rRollForce_OS_RawA_kN + rRollForce_OS_RawC_kN);
    iForceOS_FaultCounterB := iForceOS_FaultCounterB + 1;
    bForceOS_Degraded := TRUE;
ELSIF (ABS(rRollForce_OS_RawB_kN - rRollForce_OS_RawC_kN) <= c_rForceDiscrepancyLimit_kN) THEN
    rVotedForce_OS_kN := 0.5 * (rRollForce_OS_RawB_kN + rRollForce_OS_RawC_kN);
    iForceOS_FaultCounterA := iForceOS_FaultCounterA + 1;
    bForceOS_Degraded := TRUE;
ELSE
    rVotedForce_OS_kN := rRollForce_OS_RawC_kN;
    bForceVoterFailedOS := TRUE;
END_IF;

(* Assemble Diagnostic Registers *)
dwTMR_DiagnosticBits.0 := (iEntrySpeedFaultCounterA > 10);
dwTMR_DiagnosticBits.1 := (iEntrySpeedFaultCounterB > 10);
dwTMR_DiagnosticBits.2 := (iEntrySpeedFaultCounterC > 10);
dwTMR_DiagnosticBits.3 := bEntrySpeedDegraded;
dwTMR_DiagnosticBits.4 := (iExitSpeedFaultCounterA > 10);
dwTMR_DiagnosticBits.5 := (iExitSpeedFaultCounterB > 10);
dwTMR_DiagnosticBits.6 := (iExitSpeedFaultCounterC > 10);
dwTMR_DiagnosticBits.7 := bExitSpeedDegraded;
dwTMR_DiagnosticBits.8 := (iForceDS_FaultCounterA > 10);
dwTMR_DiagnosticBits.9 := (iForceDS_FaultCounterB > 10);
dwTMR_DiagnosticBits.10 := (iForceDS_FaultCounterC > 10);
dwTMR_DiagnosticBits.11 := bForceDS_Degraded;
dwTMR_DiagnosticBits.12 := (iForceOS_FaultCounterA > 10);
dwTMR_DiagnosticBits.13 := (iForceOS_FaultCounterB > 10);
dwTMR_DiagnosticBits.14 := (iForceOS_FaultCounterC > 10);
dwTMR_DiagnosticBits.15 := bForceOS_Degraded;
dwTMR_DiagnosticBits.16 := bSpeedVoterFailedEntry;
dwTMR_DiagnosticBits.17 := bSpeedVoterFailedExit;
dwTMR_DiagnosticBits.18 := bForceVoterFailedDS;
dwTMR_DiagnosticBits.19 := bForceVoterFailedOS;

rTotalRollForceFeedback_kN := rVotedForce_DS_kN + rVotedForce_OS_kN;
rDifferentialForce_kN      := rVotedForce_DS_kN - rVotedForce_OS_kN;

IF rVotedEntrySpeed_mpm > 2.0 THEN
    rElongationFeedback_pct := ((rVotedExitSpeed_mpm - rVotedEntrySpeed_mpm) / rVotedEntrySpeed_mpm) * 100.0;
ELSE
    rElongationFeedback_pct := 0.0;
END_IF;
rElongationError_pct := rTargetElongation_pct - rElongationFeedback_pct;

(* ====================================================================================================================
   SECTION 3: OPTICAL STRIP FLATNESS ORTHOGONAL LEGENDRE DECOMPOSITION
   ==================================================================================================================== *)
IF NOT bLegendreBasisInitialized THEN
    rNorm_P0 := 16.0;
    rNorm_P1 := 0.0;
    rNorm_P2 := 0.0;
    rNorm_P4 := 0.0;

    FOR iDiagnosticLoopIndex := 1 TO 16 DO
        arrZoneCoordinate_xi[iDiagnosticLoopIndex] := -1.0 + (2.0 * INT_TO_REAL(iDiagnosticLoopIndex) - 1.0) / 16.0;
        arrLegendre_P0[iDiagnosticLoopIndex] := 1.0;
        arrLegendre_P1[iDiagnosticLoopIndex] := arrZoneCoordinate_xi[iDiagnosticLoopIndex];
        rNorm_P1 := rNorm_P1 + arrLegendre_P1[iDiagnosticLoopIndex] * arrLegendre_P1[iDiagnosticLoopIndex];
        arrLegendre_P2[iDiagnosticLoopIndex] := 0.5 * (3.0 * arrZoneCoordinate_xi[iDiagnosticLoopIndex] * arrZoneCoordinate_xi[iDiagnosticLoopIndex] - 1.0);
        rNorm_P2 := rNorm_P2 + arrLegendre_P2[iDiagnosticLoopIndex] * arrLegendre_P2[iDiagnosticLoopIndex];
        arrLegendre_P4[iDiagnosticLoopIndex] := 0.125 * (35.0 * EXPT(arrZoneCoordinate_xi[iDiagnosticLoopIndex], 4) - 30.0 * EXPT(arrZoneCoordinate_xi[iDiagnosticLoopIndex], 2) + 3.0);
        rNorm_P4 := rNorm_P4 + arrLegendre_P4[iDiagnosticLoopIndex] * arrLegendre_P4[iDiagnosticLoopIndex];
    END_FOR;
    bLegendreBasisInitialized := TRUE;
END_IF;

rMeanFlatness_Iunit    := 0.0;
rFlatnessTilt_Iunit    := 0.0;
rFlatnessCrown_Iunit   := 0.0;
rFlatnessQuarter_Iunit := 0.0;

FOR iDiagnosticLoopIndex := 1 TO 16 DO
    rMeanFlatness_Iunit    := rMeanFlatness_Iunit    + arrFlatnessProfile_Iunit[iDiagnosticLoopIndex] * arrLegendre_P0[iDiagnosticLoopIndex];
    rFlatnessTilt_Iunit    := rFlatnessTilt_Iunit    + arrFlatnessProfile_Iunit[iDiagnosticLoopIndex] * arrLegendre_P1[iDiagnosticLoopIndex];
    rFlatnessCrown_Iunit   := rFlatnessCrown_Iunit   + arrFlatnessProfile_Iunit[iDiagnosticLoopIndex] * arrLegendre_P2[iDiagnosticLoopIndex];
    rFlatnessQuarter_Iunit := rFlatnessQuarter_Iunit + arrFlatnessProfile_Iunit[iDiagnosticLoopIndex] * arrLegendre_P4[iDiagnosticLoopIndex];
END_FOR;

rMeanFlatness_Iunit    := rMeanFlatness_Iunit / rNorm_P0;
rFlatnessTilt_Iunit    := rFlatnessTilt_Iunit / rNorm_P1;
rFlatnessCrown_Iunit   := rFlatnessCrown_Iunit / rNorm_P2;
rFlatnessQuarter_Iunit := rFlatnessQuarter_Iunit / rNorm_P4;

FOR iDiagnosticLoopIndex := 1 TO 16 DO
    arrFlatnessResidual_Iunit[iDiagnosticLoopIndex] := arrFlatnessProfile_Iunit[iDiagnosticLoopIndex] 
        - (rMeanFlatness_Iunit * arrLegendre_P0[iDiagnosticLoopIndex] 
         + rFlatnessTilt_Iunit * arrLegendre_P1[iDiagnosticLoopIndex] 
         + rFlatnessCrown_Iunit * arrLegendre_P2[iDiagnosticLoopIndex] 
         + rFlatnessQuarter_Iunit * arrLegendre_P4[iDiagnosticLoopIndex]);
END_FOR;

(* ====================================================================================================================
   SECTION 4: ADAPTIVE ROLL ECCENTRICITY COMPENSATION (REC) MULTI-HARMONIC FOURIER FILTER
   ==================================================================================================================== *)
rRollAngleRad_TopBUR := rBackupRollAngleTop_deg * c_rDegToRad;
rRollAngleRad_BotBUR := rBackupRollAngleBot_deg * c_rDegToRad;
rRollAngleRad_TopWR  := rWorkRollAngleTop_deg  * c_rDegToRad;
rRollAngleRad_BotWR  := rWorkRollAngleBot_deg  * c_rDegToRad;

IF (rVotedEntrySpeed_mpm >= c_rMinStripSpeedForREC_mpm) AND (iState = 40 OR iState = 50) THEN
    rEstimatedEccForceDS_kN := 0.0;
    rEstimatedEccForceOS_kN := 0.0;

    (* Top Backup Roll (Harmonics 1..4) *)
    rEstimatedEccForceDS_kN := rEstimatedEccForceDS_kN 
        + arrHarmonicCos_A[1, 1] * COS(1.0 * rRollAngleRad_TopBUR) + arrHarmonicSin_B[1, 1] * SIN(1.0 * rRollAngleRad_TopBUR)
        + arrHarmonicCos_A[1, 2] * COS(2.0 * rRollAngleRad_TopBUR) + arrHarmonicSin_B[1, 2] * SIN(2.0 * rRollAngleRad_TopBUR)
        + arrHarmonicCos_A[1, 3] * COS(3.0 * rRollAngleRad_TopBUR) + arrHarmonicSin_B[1, 3] * SIN(3.0 * rRollAngleRad_TopBUR)
        + arrHarmonicCos_A[1, 4] * COS(4.0 * rRollAngleRad_TopBUR) + arrHarmonicSin_B[1, 4] * SIN(4.0 * rRollAngleRad_TopBUR);

    (* Bottom Backup Roll (Harmonics 1..4) *)
    rEstimatedEccForceDS_kN := rEstimatedEccForceDS_kN 
        + arrHarmonicCos_A[2, 1] * COS(1.0 * rRollAngleRad_BotBUR) + arrHarmonicSin_B[2, 1] * SIN(1.0 * rRollAngleRad_BotBUR)
        + arrHarmonicCos_A[2, 2] * COS(2.0 * rRollAngleRad_BotBUR) + arrHarmonicSin_B[2, 2] * SIN(2.0 * rRollAngleRad_BotBUR)
        + arrHarmonicCos_A[2, 3] * COS(3.0 * rRollAngleRad_BotBUR) + arrHarmonicSin_B[2, 3] * SIN(3.0 * rRollAngleRad_BotBUR)
        + arrHarmonicCos_A[2, 4] * COS(4.0 * rRollAngleRad_BotBUR) + arrHarmonicSin_B[2, 4] * SIN(4.0 * rRollAngleRad_BotBUR);

    (* Top Work Roll (Harmonics 1..2) *)
    rEstimatedEccForceDS_kN := rEstimatedEccForceDS_kN 
        + arrHarmonicCos_A[3, 1] * COS(1.0 * rRollAngleRad_TopWR)  + arrHarmonicSin_B[3, 1] * SIN(1.0 * rRollAngleRad_TopWR)
        + arrHarmonicCos_A[3, 2] * COS(2.0 * rRollAngleRad_TopWR)  + arrHarmonicSin_B[3, 2] * SIN(2.0 * rRollAngleRad_TopWR);

    (* Bottom Work Roll (Harmonics 1..2) *)
    rEstimatedEccForceDS_kN := rEstimatedEccForceDS_kN 
        + arrHarmonicCos_A[4, 1] * COS(1.0 * rRollAngleRad_BotWR)  + arrHarmonicSin_B[4, 1] * SIN(1.0 * rRollAngleRad_BotWR)
        + arrHarmonicCos_A[4, 2] * COS(2.0 * rRollAngleRad_BotWR)  + arrHarmonicSin_B[4, 2] * SIN(2.0 * rRollAngleRad_BotWR);

    rEstimatedEccForceOS_kN := rEstimatedEccForceDS_kN * 0.985;

    IF iState = 50 THEN
        arrHarmonicCos_A[1, 1] := arrHarmonicCos_A[1, 1] + rRLS_LearningGain * (rVotedForce_DS_kN - rEstimatedEccForceDS_kN) * COS(1.0 * rRollAngleRad_TopBUR);
        arrHarmonicSin_B[1, 1] := arrHarmonicSin_B[1, 1] + rRLS_LearningGain * (rVotedForce_DS_kN - rEstimatedEccForceDS_kN) * SIN(1.0 * rRollAngleRad_TopBUR);
        arrHarmonicCos_A[1, 2] := arrHarmonicCos_A[1, 2] + rRLS_LearningGain * (rVotedForce_DS_kN - rEstimatedEccForceDS_kN) * COS(2.0 * rRollAngleRad_TopBUR);
        arrHarmonicSin_B[1, 2] := arrHarmonicSin_B[1, 2] + rRLS_LearningGain * (rVotedForce_DS_kN - rEstimatedEccForceDS_kN) * SIN(2.0 * rRollAngleRad_TopBUR);

        arrHarmonicCos_A[2, 1] := arrHarmonicCos_A[2, 1] + rRLS_LearningGain * (rVotedForce_DS_kN - rEstimatedEccForceDS_kN) * COS(1.0 * rRollAngleRad_BotBUR);
        arrHarmonicSin_B[2, 1] := arrHarmonicSin_B[2, 1] + rRLS_LearningGain * (rVotedForce_DS_kN - rEstimatedEccForceDS_kN) * SIN(1.0 * rRollAngleRad_BotBUR);
        arrHarmonicCos_A[2, 2] := arrHarmonicCos_A[2, 2] + rRLS_LearningGain * (rVotedForce_DS_kN - rEstimatedEccForceDS_kN) * COS(2.0 * rRollAngleRad_BotBUR);
        arrHarmonicSin_B[2, 2] := arrHarmonicSin_B[2, 2] + rRLS_LearningGain * (rVotedForce_DS_kN - rEstimatedEccForceDS_kN) * SIN(2.0 * rRollAngleRad_BotBUR);
    END_IF;

    rEccentricityComp_DS_mm := -1.0 * (rEstimatedEccForceDS_kN / c_rMillModulus_kN_per_mm) * rEccentricityCompGain;
    rEccentricityComp_OS_mm := -1.0 * (rEstimatedEccForceOS_kN / c_rMillModulus_kN_per_mm) * rEccentricityCompGain;

    IF rEccentricityComp_DS_mm > 0.35 THEN rEccentricityComp_DS_mm := 0.35; END_IF;
    IF rEccentricityComp_DS_mm < -0.35 THEN rEccentricityComp_DS_mm := -0.35; END_IF;
    IF rEccentricityComp_OS_mm > 0.35 THEN rEccentricityComp_OS_mm := 0.35; END_IF;
    IF rEccentricityComp_OS_mm < -0.35 THEN rEccentricityComp_OS_mm := -0.35; END_IF;
ELSE
    rEccentricityComp_DS_mm := 0.0;
    rEccentricityComp_OS_mm := 0.0;
END_IF;

(* ====================================================================================================================
   SECTION 5: MODEL PREDICTIVE CONTROL (MPC) STATE-SPACE ENGINE & PROJECTED GRADIENT SOLVER
   ==================================================================================================================== *)
IF NOT bMPC_MatricesInitialized THEN
    matA[1,1] := 0.965;  matA[1,2] := 0.000;  matA[1,3] := 0.000;  matA[1,4] := 0.00012; matA[1,5] := 0.000;   matA[1,6] := 0.000;
    matA[2,1] := 0.000;  matA[2,2] := 0.940;  matA[2,3] := 0.000;  matA[2,4] := 0.000;   matA[2,5] := 0.00185; matA[2,6] := 0.000;
    matA[3,1] := 0.000;  matA[3,2] := 0.000;  matA[3,3] := 0.925;  matA[3,4] := 0.000;   matA[3,5] := 0.000;   matA[3,6] := 0.0042;
    matA[4,1] := -15.2;  matA[4,2] := 0.000;  matA[4,3] := 0.000;  matA[4,4] := 0.880;   matA[4,5] := 0.000;   matA[4,6] := 0.000;
    matA[5,1] := 0.000;  matA[5,2] := -2.40;  matA[5,3] := 0.000;  matA[5,4] := 0.000;   matA[5,5] := 0.850;   matA[5,6] := 0.000;
    matA[6,1] := 0.000;  matA[6,2] := 0.000;  matA[6,3] := -1.15;  matA[6,4] := 0.000;   matA[6,5] := 0.000;   matA[6,6] := 0.910;

    matB[1,1] := -1.850; matB[1,2] := 0.000;  matB[1,3] := 0.0000; matB[1,4] := 0.0450;
    matB[2,1] := 0.000;  matB[2,2] := -4.250; matB[2,3] := 0.0000; matB[2,4] := 0.0000;
    matB[3,1] := 0.000;  matB[3,2] := 0.000;  matB[3,3] := 0.0820; matB[3,4] := 0.0000;
    matB[4,1] := 4250.0; matB[4,2] := 0.000;  matB[4,3] := 0.0000; matB[4,4] := -12.50;
    matB[5,1] := 0.000;  matB[5,2] := 2150.0; matB[5,3] := 0.0000; matB[5,4] := 0.0000;
    matB[6,1] := 0.000;  matB[6,2] := 0.000;  matB[6,3] := 0.8500; matB[6,4] := 0.0000;

    matC[1,1] := 1.0; matC[1,2] := 0.0; matC[1,3] := 0.0; matC[1,4] := 0.0; matC[1,5] := 0.0; matC[1,6] := 0.0;
    matC[2,1] := 0.0; matC[2,2] := 1.0; matC[2,3] := 0.0; matC[2,4] := 0.0; matC[2,5] := 0.0; matC[2,6] := 0.0;
    matC[3,1] := 0.0; matC[3,2] := 0.0; matC[3,3] := 1.0; matC[3,4] := 0.0; matC[3,5] := 0.0; matC[3,6] := 0.0;
    matC[4,1] := 0.0; matC[4,2] := 0.0; matC[4,3] := 0.0; matC[4,4] := 1.0; matC[4,5] := 0.0; matC[4,6] := 0.0;

    FOR iDiagnosticLoopIndex := 1 TO 4 DO
        matD[iDiagnosticLoopIndex, 1] := 0.0;
        matD[iDiagnosticLoopIndex, 2] := 0.0;
        matD[iDiagnosticLoopIndex, 3] := 0.0;
        matD[iDiagnosticLoopIndex, 4] := 0.0;
    END_FOR;

    vecCostWeight_Q[1] := 1250.0;
    vecCostWeight_Q[2] := 85.0;
    vecCostWeight_Q[3] := 120.0;
    vecCostWeight_Q[4] := 0.005;
    vecCostWeight_Q[5] := 0.020;
    vecCostWeight_Q[6] := 0.010;

    vecCostWeight_R[1] := 25.0;
    vecCostWeight_R[2] := 35.0;
    vecCostWeight_R[3] := 0.05;
    vecCostWeight_R[4] := 0.15;

    vecCostWeight_S[1] := 80.0;
    vecCostWeight_S[2] := 100.0;
    vecCostWeight_S[3] := 1.5;
    vecCostWeight_S[4] := 2.0;

    vecControlMin_u[1] := -0.80; vecControlMax_u[1] := 0.80;
    vecControlMin_u[2] := -0.40; vecControlMax_u[2] := 0.40;
    vecControlMin_u[3] := c_rMaxBendingForceNegative_kN; vecControlMax_u[3] := c_rMaxBendingForcePositive_kN;
    vecControlMin_u[4] := -25.0; vecControlMax_u[4] := 25.0;

    vecDeltaMax_du[1]  := 0.015;
    vecDeltaMax_du[2]  := 0.010;
    vecDeltaMax_du[3]  := 8.0;
    vecDeltaMax_du[4]  := 0.5;

    bMPC_MatricesInitialized := TRUE;
END_IF;

vecState_x[1] := rElongationError_pct;
vecState_x[2] := 0.0 - rFlatnessTilt_Iunit;
vecState_x[3] := 0.0 - rFlatnessCrown_Iunit;
vecState_x[4] := rTotalRollForceFeedback_kN - c_rKissPassCalibrationForce_kN * 5.0;
vecState_x[5] := rDifferentialForce_kN;
vecState_x[6] := rWorkRollBendingCmd_kN - rTargetBendingForce_kN;

IF (iState = 50 OR iState = 60) AND bEnable THEN
    FOR iDiagnosticLoopIndex := 1 TO iMPC_MaxIterations DO
        vecStateNext_x[1] := matA[1,1]*vecState_x[1] + matA[1,4]*vecState_x[4] + matB[1,1]*vecControl_u[1] + matB[1,4]*vecControl_u[4];
        vecStateNext_x[2] := matA[2,2]*vecState_x[2] + matA[2,5]*vecState_x[5] + matB[2,2]*vecControl_u[2];
        vecStateNext_x[3] := matA[3,3]*vecState_x[3] + matA[3,6]*vecState_x[6] + matB[3,3]*vecControl_u[3];
        vecStateNext_x[4] := matA[4,1]*vecState_x[1] + matA[4,4]*vecState_x[4] + matB[4,1]*vecControl_u[1] + matB[4,4]*vecControl_u[4];
        vecStateNext_x[5] := matA[5,2]*vecState_x[2] + matA[5,5]*vecState_x[5] + matB[5,2]*vecControl_u[2];
        vecStateNext_x[6] := matA[6,3]*vecState_x[3] + matA[6,6]*vecState_x[6] + matB[6,3]*vecControl_u[3];

        vecGradient_g[1] := matB[1,1] * vecCostWeight_Q[1] * vecStateNext_x[1] 
                          + matB[4,1] * vecCostWeight_Q[4] * vecStateNext_x[4] 
                          + vecCostWeight_R[1] * vecControl_u[1] 
                          + vecCostWeight_S[1] * (vecControl_u[1] - vecControlPrev_u[1]);

        vecGradient_g[2] := matB[2,2] * vecCostWeight_Q[2] * vecStateNext_x[2] 
                          + matB[5,2] * vecCostWeight_Q[5] * vecStateNext_x[5] 
                          + vecCostWeight_R[2] * vecControl_u[2] 
                          + vecCostWeight_S[2] * (vecControl_u[2] - vecControlPrev_u[2]);

        vecGradient_g[3] := matB[3,3] * vecCostWeight_Q[3] * vecStateNext_x[3] 
                          + matB[6,3] * vecCostWeight_Q[6] * vecStateNext_x[6] 
                          + vecCostWeight_R[3] * vecControl_u[3] 
                          + vecCostWeight_S[3] * (vecControl_u[3] - vecControlPrev_u[3]);

        vecGradient_g[4] := matB[1,4] * vecCostWeight_Q[1] * vecStateNext_x[1] 
                          + matB[4,4] * vecCostWeight_Q[4] * vecStateNext_x[4] 
                          + vecCostWeight_R[4] * vecControl_u[4] 
                          + vecCostWeight_S[4] * (vecControl_u[4] - vecControlPrev_u[4]);

        vecControl_u[1] := vecControl_u[1] - rMPC_StepSizeAlpha * vecGradient_g[1];
        vecControl_u[2] := vecControl_u[2] - rMPC_StepSizeAlpha * vecGradient_g[2];
        vecControl_u[3] := vecControl_u[3] - rMPC_StepSizeAlpha * vecGradient_g[3];
        vecControl_u[4] := vecControl_u[4] - rMPC_StepSizeAlpha * vecGradient_g[4];

        vecDeltaControl_du[1] := vecControl_u[1] - vecControlPrev_u[1];
        IF vecDeltaControl_du[1] > vecDeltaMax_du[1] THEN vecControl_u[1] := vecControlPrev_u[1] + vecDeltaMax_du[1]; END_IF;
        IF vecDeltaControl_du[1] < -vecDeltaMax_du[1] THEN vecControl_u[1] := vecControlPrev_u[1] - vecDeltaMax_du[1]; END_IF;

        vecDeltaControl_du[2] := vecControl_u[2] - vecControlPrev_u[2];
        IF vecDeltaControl_du[2] > vecDeltaMax_du[2] THEN vecControl_u[2] := vecControlPrev_u[2] + vecDeltaMax_du[2]; END_IF;
        IF vecDeltaControl_du[2] < -vecDeltaMax_du[2] THEN vecControl_u[2] := vecControlPrev_u[2] - vecDeltaMax_du[2]; END_IF;

        vecDeltaControl_du[3] := vecControl_u[3] - vecControlPrev_u[3];
        IF vecDeltaControl_du[3] > vecDeltaMax_du[3] THEN vecControl_u[3] := vecControlPrev_u[3] + vecDeltaMax_du[3]; END_IF;
        IF vecDeltaControl_du[3] < -vecDeltaMax_du[3] THEN vecControl_u[3] := vecControlPrev_u[3] - vecDeltaMax_du[3]; END_IF;

        IF vecControl_u[1] < vecControlMin_u[1] THEN vecControl_u[1] := vecControlMin_u[1]; END_IF;
        IF vecControl_u[1] > vecControlMax_u[1] THEN vecControl_u[1] := vecControlMax_u[1]; END_IF;

        IF vecControl_u[2] < vecControlMin_u[2] THEN vecControl_u[2] := vecControlMin_u[2]; END_IF;
        IF vecControl_u[2] > vecControlMax_u[2] THEN vecControl_u[2] := vecControlMax_u[2]; END_IF;

        IF vecControl_u[3] < vecControlMin_u[3] THEN vecControl_u[3] := vecControlMin_u[3]; END_IF;
        IF vecControl_u[3] > vecControlMax_u[3] THEN vecControl_u[3] := vecControlMax_u[3]; END_IF;
    END_FOR;

    vecControlPrev_u[1] := vecControl_u[1];
    vecControlPrev_u[2] := vecControl_u[2];
    vecControlPrev_u[3] := vecControl_u[3];
    vecControlPrev_u[4] := vecControl_u[4];
ELSE
    vecControl_u[1] := 0.0;
    vecControl_u[2] := 0.0;
    vecControl_u[3] := 0.0;
    vecControl_u[4] := 0.0;
    vecControlPrev_u[1] := 0.0;
    vecControlPrev_u[2] := 0.0;
    vecControlPrev_u[3] := 0.0;
    vecControlPrev_u[4] := 0.0;
END_IF;

(* ====================================================================================================================
   SECTION 6: MULTI-STAGE FINITE STATE MACHINE (CASE iState OF)
   ==================================================================================================================== *)
CASE iState OF
    0: (* ---------------- STATE 0: STANDBY & SYSTEM INITIALIZATION ---------------- *)
        bSystemReady            := FALSE;
        bControlActive          := FALSE;
        bDegradedMode           := FALSE;
        bSystemAlarm            := FALSE;
        wFaultCode              := 16#0000;
        rServoCmdGap_DS_mm      := rBaseGapPosition_DS_mm;
        rServoCmdGap_OS_mm      := rBaseGapPosition_OS_mm;
        rWorkRollBendingCmd_kN  := 0.0;

        IF bEnable AND bEmergencyStopOk THEN
            IF bCalibrationMode THEN
                iState := 20;
            ELSE
                iState := 10;
            END_IF;
        END_IF;

    10: (* ------------ STATE 10: HYDRAULIC SERVO PRECHARGE & WARMUP ------------ *)
        bSystemReady       := TRUE;
        bControlActive     := FALSE;
        rServoCmdGap_DS_mm := rBaseGapPosition_DS_mm;
        rServoCmdGap_OS_mm := rBaseGapPosition_OS_mm;

        tStepTimer(IN := TRUE, PT := T#2S);
        IF tStepTimer.Q THEN
            tStepTimer(IN := FALSE);
            iState := 30;
        END_IF;

    20: (* ----------- STATE 20: AUTOMATED KISS-PASS ZERO CALIBRATION ----------- *)
        bSystemReady   := FALSE;
        bControlActive := FALSE;

        IF (rTotalRollForceFeedback_kN < c_rKissPassCalibrationForce_kN) THEN
            rServoCmdGap_DS_mm := rServoCmdGap_DS_mm - 0.005;
            rServoCmdGap_OS_mm := rServoCmdGap_OS_mm - 0.005;
            tKissCalibrationTimer(IN := FALSE);
        ELSE
            tKissCalibrationTimer(IN := TRUE, PT := T#1500MS);
            IF tKissCalibrationTimer.Q THEN
                rZeroGapOffset_DS_mm := rRollGap_DS_mm;
                rZeroGapOffset_OS_mm := rRollGap_OS_mm;
                tKissCalibrationTimer(IN := FALSE);
                iState := 0;
            END_IF;
        END_IF;

    30: (* ---------- STATE 30: THREADING LOW-SPEED SYNCHRONIZATION ---------- *)
        bSystemReady       := TRUE;
        bControlActive     := FALSE;
        rServoCmdGap_DS_mm := rZeroGapOffset_DS_mm + 1.25;
        rServoCmdGap_OS_mm := rZeroGapOffset_OS_mm + 1.25;
        rWorkRollBendingCmd_kN := rTargetBendingForce_kN * 0.35;

        IF (rVotedEntrySpeed_mpm > 15.0) AND (rTotalRollForceFeedback_kN > 800.0) THEN
            iState := 40;
        END_IF;

    40: (* -------- STATE 40: ACCELERATION & ROLL ECCENTRICITY LEARNING -------- *)
        bSystemReady   := TRUE;
        bControlActive := TRUE;

        rServoCmdGap_DS_mm := rZeroGapOffset_DS_mm + vecControl_u[1] + 0.5 * vecControl_u[2] + rEccentricityComp_DS_mm;
        rServoCmdGap_OS_mm := rZeroGapOffset_OS_mm + vecControl_u[1] - 0.5 * vecControl_u[2] + rEccentricityComp_OS_mm;
        rWorkRollBendingCmd_kN := rTargetBendingForce_kN;

        IF rVotedEntrySpeed_mpm >= c_rMinStripSpeedForREC_mpm THEN
            iState := 50;
        END_IF;

    50: (* ---------- STATE 50: FULL STEADY-STATE PRODUCTION MPC ACTIVE ---------- *)
        bSystemReady   := TRUE;
        bControlActive := TRUE;
        bDegradedMode  := FALSE;

        rServoCmdGap_DS_mm := rZeroGapOffset_DS_mm + vecControl_u[1] + 0.5 * vecControl_u[2] + rEccentricityComp_DS_mm;
        rServoCmdGap_OS_mm := rZeroGapOffset_OS_mm + vecControl_u[1] - 0.5 * vecControl_u[2] + rEccentricityComp_OS_mm;
        rWorkRollBendingCmd_kN := rTargetBendingForce_kN + vecControl_u[3];

        IF bEntrySpeedDegraded OR bExitSpeedDegraded OR bForceDS_Degraded OR bForceOS_Degraded THEN
            iState := 60;
        END_IF;

        IF bTailOutApproaching THEN
            iState := 70;
        END_IF;

    60: (* ---------- STATE 60: DEGRADED OPERATION (FAIL-SOFT CONTROL) ---------- *)
        bSystemReady   := TRUE;
        bControlActive := TRUE;
        bDegradedMode  := TRUE;
        wWarningWord.0 := TRUE;

        rServoCmdGap_DS_mm := rZeroGapOffset_DS_mm + 0.70 * (vecControl_u[1] + 0.5 * vecControl_u[2]) + rEccentricityComp_DS_mm;
        rServoCmdGap_OS_mm := rZeroGapOffset_OS_mm + 0.70 * (vecControl_u[1] - 0.5 * vecControl_u[2]) + rEccentricityComp_OS_mm;
        rWorkRollBendingCmd_kN := rTargetBendingForce_kN;

        IF NOT (bEntrySpeedDegraded OR bExitSpeedDegraded OR bForceDS_Degraded OR bForceOS_Degraded) THEN
            iState := 50;
        END_IF;

        IF bTailOutApproaching THEN
            iState := 70;
        END_IF;

    70: (* -------------- STATE 70: STRIP DECELERATION & TAIL-OUT -------------- *)
        bSystemReady   := TRUE;
        bControlActive := FALSE;

        rServoCmdGap_DS_mm := rServoCmdGap_DS_mm + 0.020;
        rServoCmdGap_OS_mm := rServoCmdGap_OS_mm + 0.020;
        rWorkRollBendingCmd_kN := 0.0;
        rEccentricityComp_DS_mm := 0.0;
        rEccentricityComp_OS_mm := 0.0;

        tTailoutDecelTimer(IN := TRUE, PT := T#1200MS);
        IF tTailoutDecelTimer.Q OR (rTotalRollForceFeedback_kN < 300.0) THEN
            tTailoutDecelTimer(IN := FALSE);
            iState := 80;
        END_IF;

    80: (* ------------ STATE 80: CONTROLLED RETRACT TO STANDBY GAP ------------ *)
        bSystemReady   := TRUE;
        bControlActive := FALSE;
        bDegradedMode  := FALSE;
        rWorkRollBendingCmd_kN := 0.0;

        IF rServoCmdGap_DS_mm < rBaseGapPosition_DS_mm THEN
            rServoCmdGap_DS_mm := rServoCmdGap_DS_mm + 0.100;
        ELSE
            rServoCmdGap_DS_mm := rBaseGapPosition_DS_mm;
        END_IF;

        IF rServoCmdGap_OS_mm < rBaseGapPosition_OS_mm THEN
            rServoCmdGap_OS_mm := rServoCmdGap_OS_mm + 0.100;
        ELSE
            rServoCmdGap_OS_mm := rBaseGapPosition_OS_mm;
        END_IF;

        IF (rServoCmdGap_DS_mm >= rBaseGapPosition_DS_mm) AND (rServoCmdGap_OS_mm >= rBaseGapPosition_OS_mm) THEN
            iState := 0;
        END_IF;

    90: (* ------------ STATE 90: CONTROLLED SYSTEM TRIP & ABORT ------------ *)
        bSystemReady   := FALSE;
        bControlActive := FALSE;
        bSystemAlarm   := TRUE;
        rWorkRollBendingCmd_kN := 0.0;
        rEccentricityComp_DS_mm := 0.0;
        rEccentricityComp_OS_mm := 0.0;

        IF rServoCmdGap_DS_mm < c_rMaxHydraulicStroke_mm THEN
            rServoCmdGap_DS_mm := rServoCmdGap_DS_mm + 0.500;
        END_IF;
        IF rServoCmdGap_OS_mm < c_rMaxHydraulicStroke_mm THEN
            rServoCmdGap_OS_mm := rServoCmdGap_OS_mm + 0.500;
        END_IF;

        IF bResetAlarms AND bEmergencyStopOk THEN
            bSystemAlarm := FALSE;
            wFaultCode   := 16#0000;
            iState       := 0;
        END_IF;

    99: (* ----------- STATE 99: CRITICAL HARDWARE EMERGENCY INTERLOCK ----------- *)
        bSystemReady            := FALSE;
        bControlActive          := FALSE;
        bSystemAlarm            := TRUE;
        rServoCmdGap_DS_mm      := c_rMaxHydraulicStroke_mm;
        rServoCmdGap_OS_mm      := c_rMaxHydraulicStroke_mm;
        rWorkRollBendingCmd_kN  := 0.0;
        rEccentricityComp_DS_mm := 0.0;
        rEccentricityComp_OS_mm := 0.0;

        IF bResetAlarms AND bEmergencyStopOk THEN
            bSystemAlarm := FALSE;
            wFaultCode   := 16#0000;
            iState       := 0;
        END_IF;

END_CASE;

(* ====================================================================================================================
   SECTION 7: MULTI-ZONE THERMAL ROLL COOLING PULSE-WIDTH MODULATION (16 ZONES)
   ==================================================================================================================== *)
IF (iState = 50 OR iState = 60) AND (rVotedEntrySpeed_mpm > 50.0) THEN
    FOR iDiagnosticLoopIndex := 1 TO 16 DO
        arrCoolingZoneTrim_pct[iDiagnosticLoopIndex] := 25.0 + arrFlatnessResidual_Iunit[iDiagnosticLoopIndex] * 3.5;
        IF arrCoolingZoneTrim_pct[iDiagnosticLoopIndex] < 0.0 THEN
            arrCoolingZoneTrim_pct[iDiagnosticLoopIndex] := 0.0;
        ELSIF arrCoolingZoneTrim_pct[iDiagnosticLoopIndex] > 100.0 THEN
            arrCoolingZoneTrim_pct[iDiagnosticLoopIndex] := 100.0;
        END_IF;
    END_FOR;
ELSE
    FOR iDiagnosticLoopIndex := 1 TO 16 DO
        arrCoolingZoneTrim_pct[iDiagnosticLoopIndex] := 0.0;
    END_FOR;
END_IF;

(* ====================================================================================================================
   SECTION 8: COMPREHENSIVE ALARM TREE, FAULT ENCODING & GRACEFUL DEGRADATION
   ==================================================================================================================== *)
bExcessiveRollForce := (rTotalRollForceFeedback_kN >= c_rMaxAllowableRollForce_kN);
bStripBreakageSuspected := (iState = 50) AND (rTotalRollForceFeedback_kN < 200.0) AND (rVotedEntrySpeed_mpm > 50.0);

IF bExcessiveRollForce THEN
    wFaultCode   := 16#0002; (* ROLL_FORCE_EXCEEDED_MAX_LIMIT_22000_KN *)
    bSystemAlarm := TRUE;
    iState       := 90;
ELSIF bStripBreakageSuspected THEN
    wFaultCode   := 16#0003; (* CATASTROPHIC_STRIP_BREAKAGE_DETECTED *)
    bSystemAlarm := TRUE;
    iState       := 90;
ELSIF bSpeedVoterFailedEntry AND bSpeedVoterFailedExit THEN
    wFaultCode   := 16#0004; (* COMPLETE_LOSS_OF_VELOCITY_INSTRUMENTATION *)
    bSystemAlarm := TRUE;
    iState       := 90;
ELSIF bForceVoterFailedDS AND bForceVoterFailedOS THEN
    wFaultCode   := 16#0005; (* COMPLETE_LOSS_OF_FORCE_LOADCELLS *)
    bSystemAlarm := TRUE;
    iState       := 90;
END_IF;

bExcessiveElongationError    := (ABS(rElongationError_pct) > 0.25) AND (iState = 50);
bExcessiveFlatnessDistortion := (ABS(rFlatnessCrown_Iunit) > 25.0) OR (ABS(rFlatnessTilt_Iunit) > 30.0);
bHydraulicGapSaturation      := (vecControl_u[1] >= vecControlMax_u[1]) OR (vecControl_u[1] <= vecControlMin_u[1]);
bBendingSaturation           := (rWorkRollBendingCmd_kN >= c_rMaxBendingForcePositive_kN) OR (rWorkRollBendingCmd_kN <= c_rMaxBendingForceNegative_kN);

wWarningWord.1 := bExcessiveElongationError;
wWarningWord.2 := bExcessiveFlatnessDistortion;
wWarningWord.3 := bHydraulicGapSaturation;
wWarningWord.4 := bBendingSaturation;
wWarningWord.5 := bEntrySpeedDegraded;
wWarningWord.6 := bExitSpeedDegraded;
wWarningWord.7 := bForceDS_Degraded;
wWarningWord.8 := bForceOS_Degraded;

iStateSequence := iState;

END_FUNCTION_BLOCK
